# 数据文件：src/components/memory/MemoryFileSelector.tsx
# slug = src_components_memory_MemoryFileSelector_tsx
# 规则：一个源文件 = 一个数据文件；中文用三引号；禁止英文双引号 " 与反斜杠 \（用「」』代替）。
ANNOTATIONS = [
    (1, 'before', '''本文件是记忆文件选择器：列出用户级与项目级的记忆文件（含被导入的嵌套文件），再挂上几个「打开某个目录」的入口，外加两个开关（自动记忆、自动整理）。它同时是三个角色的混合体——文件列表、目录快捷入口、配置开关，三者共用一套上下键。最值得读的是这三者如何在一个键盘模型里排队：开关行占据列表上方的位置，但只有上键从第一项再向上时才接管。'''),
    (28, 'before', '''条件加载：团队记忆相关模块只在特性开关开启时用 require 拉进来，并显式禁用了那条「禁止 require」的检查规则。这样外部构建里整个模块会被摇掉，界面代码不必到处写特性判断。这种「用 require 换掉静态导入」的做法在打包体积敏感的地方很常见，代价是类型要靠手写断言补回来。'''),
    (32, 'before', '''扩展后的文件信息多了两个字段：是否嵌套（被导入进来的）、是否存在。后面所有「新建」标记与缩进层级都基于这两个字段，所以它必须在进入渲染之前就被补齐。'''),
    (38, 'before', '''模块级变量记住上次选中的路径。用模块级而不是状态，是因为它的生命周期要跨组件实例——用户打开选择器、选一个文件、离开、再打开，希望光标停在上次那个文件上。这是少数几个「模块级可变状态」合理的场景。'''),
    (44, 'before', '''组件本体。第一个钩子是同步读取记忆文件的「资源钩子」——它接收一个承诺而不是直接返回值，会在承诺未完成时挂起组件。这意味着本组件第一次渲染前就已经拿到了完整文件清单，没有加载态分支。'''),
    (50, 'before', '''全文件的数据来源就是这一行：一个异步清单。后面所有内容都是这份清单的派生——补默认项、算层级、拼标签、加目录入口。理解这一点之后，中间那一大段嵌套条件其实只是在为每条文件算「标签」与「描述」两句话。'''),
    (55, 'before', '''三条来源拼成完整清单：已有的记忆文件（滤掉自动记忆与团队记忆两类，因为它们走目录入口而不是文件入口）、以及「若没有用户级文件就补一个占位的新建项」、再加「若没有项目级文件就补一个」。占位项的内容为空、存在标记为假，于是会在标签后面显示新建提示。'''),
    (66, 'before', '''层级表用普通映射而不是给每个对象加字段，因为原对象来自外部、不该被就地修改。映射的键是路径，值是深度——下面的循环按清单顺序推进，父文件必然排在子文件之前，所以查父级的深度总是命中。这个隐含前提是本文件最容易忽略的一处依赖。'''),
    (74, 'before', '''标签的三级判定：用户级主文件叫「用户记忆」、项目级主文件叫「项目记忆」、其余带层级时前面加缩进与一个折角符号。缩进用重复空格而不是组件内边距，是为了让折角符号与上一层的文字精确对齐。'''),
    (88, 'before', '''描述文案同样分级，而且第一层的判断依赖「当前目录是不是 git 仓库」——在仓库里说「已提交在」，否则说「保存在」。这个差别对用户很重要：前者意味着改动会被版本管理带走，后者不会。'''),
    (112, 'before', '''目录入口数组独立于文件清单，最后才拼到清单尾部。这样文件与目录在同一个下拉框里，但生成逻辑完全分开——文件来自扫描，目录来自配置。'''),
    (114, 'before', '''自动记忆开启时才给目录入口。关掉时既不给入口、也不给下面的开关行之一，等于把整块能力从界面里摘掉，而不是显示成禁用。'''),
    (127, 'before', '''团队记忆入口再套一层特性开关与运行时开关的双重判断。特性开关决定代码是否存在，运行时开关决定这个团队是否真的启用了——两者都成立才显示。'''),
    (141, 'before', '''遍历活跃代理，为每个「声明了记忆范围」的代理生成一个目录入口，标签里带加粗的代理名、描述里写范围。这说明记忆目录是按代理分片的，界面在这里把分片暴露出来。'''),
    (155, 'before', '''初始聚焦值：上次选中的路径如果还在清单里就用它，否则用第一项。这个「还在清单里」的检查不能省——上次选的可能是某个已被删除的文件。'''),
    (162, 'before', '''三个开关状态：自动记忆、自动整理、是否显示整理行。前两个是可写的本地镜像（写设置时同步更新），第三个只在初始化时取一次——因为「是否显示」取决于能力是否可用，运行期间不会变。'''),
    (169, 'before', '''读上次整理时间：只在显示整理行时才读，读到后写入状态。副作用依赖里还包含「是否正在运行」，所以整理任务开始或结束时都会重新读一次时间——这就是界面能自动刷新「正在运行 / 上次运行于」的原因。'''),
    (192, 'before', '''整理状态三态：正在运行时优先显示「运行中」；否则时间为空显示空串（还没读过）；时间为零显示「从未」；其余显示相对时间。零与空是两种不同状态，这个区分让「从未整理过」与「还不知道」在界面上不混淆。'''),
    (200, 'before', '''开关焦点用「下标或空」表示：空表示焦点在下方列表里，零与一表示焦点在第几个开关上。用一个可空数字同时表达「有没有焦点」与「焦点在哪」，比两个变量更难写错。'''),
    (205, 'before', '''自动记忆开关：写设置、更新本地镜像、打点，三步固定顺序。先写设置再改本地状态，是为了让写失败时界面不领先于真实配置——这是配置类开关的通用写法。'''),
    (239, 'before', '''挂载退出快捷键。注意它的返回值被丢弃了——这个钩子的作用是注册「连按两次退出键」的行为，调用即生效，不需要读返回值。'''),
    (279, 'before', '''确认键的绑定带激活条件：只有焦点在开关上时才生效。这一条是三个角色共用键盘的关键——焦点在列表里时，确认键归列表；焦点在开关上时，确认键归开关。'''),
    (282, 'before', '''下一个键的处理：焦点为空时不动；焦点还没到最后一个开关时加一；已经在最后一个时清空焦点（回到列表）。所以从开关区向下会自然回到列表，形成一个环。'''),
    (303, 'before', '''上一个键的处理用了一个独立的钳制函数（文件末尾），语义是「只有大于零才减一」。配合下面列表的「从第一项再向上」，两个方向合起来构成了「列表 ↔ 开关区」的双向通道。'''),
    (327, 'before', '''自动记忆行：聚焦判定是「焦点下标等于零」。第一行用列表项组件（带聚焦样式），第二行则手写样式——两行实现方式不同，是因为第二行还要拼状态文字与运行提示，用组件反而更绕。'''),
    (343, 'before', '''自动整理行：只在显示整理行时存在，样式自己写（关掉了组件的默认样式），状态文字后面按情况追加「整理状态」与「用某命令运行」两段提示。后者只在「没在运行且开关是开的」时出现，避免在已经运行时提示用户去运行。'''),
    (365, 'before', '''选中处理分两支：以目录前缀开头的值表示「打开目录」——先递归创建目录（可能还不存在）、再调用系统打开，且创建失败被静默吞掉后仍然尝试打开；其余值才是真的选了文件，此时先记住路径再回调。先创建再打开这个顺序很重要，否则新用户的自动记忆目录还不存在，打开会失败。'''),
    (391, 'before', '''下拉框的禁用条件就是「焦点在开关区」——焦点离开列表时整个列表变灰，视觉上明确了键盘此刻归谁。这个「用禁用表达焦点归属」的手法，比在列表上方加一行提示更直接。'''),
    (414, 'before', '''钳制函数：焦点为空或已经为零时原样返回同一个值，否则减一。返回同一个引用而不是新值，是让状态更新在边界上成为空操作，避免无意义的重渲染。'''),
]
